import com.echoagent.sdk.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.security.*;import java.time.*;
public class PermissionTtl {
 static final ObjectMapper JSON=new ObjectMapper();static final Path ROOT=Path.of("/Users/ls/MyWork/code/ylp_agent_learn/lp-agent/.worktrees/admin/sdk-real-permission-ttl-runtime"),WORK=ROOT.resolve("java");static final long START=System.nanoTime();static final ArrayNode ROWS=JSON.createArrayNode();
 static <T>T await(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(15,TimeUnit.SECONDS);}
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static long nowMs(){return (System.nanoTime()-START)/1_000_000;}
 static void save(String phase,ObjectNode extra)throws Exception{var o=JSON.createObjectNode().put("language","java").put("runner_pid",ProcessHandle.current().pid()).put("phase",phase).put("elapsed_ms",nowMs()).put("wall_time",Instant.now().toString());o.set("rows",ROWS);o.setAll(extra);JSON.writerWithDefaultPrettyPrinter().writeValue(WORK.resolve("status.json").toFile(),o);}
 static JsonNode call(SessionHandle session,String operation,List<?> args)throws Exception{long before=System.nanoTime();var value=await(session.invoke(operation,args));var o=ROWS.addObject().put("operation",operation).put("elapsed_ms",nowMs()).put("call_duration_ms",(System.nanoTime()-before)/1_000_000.0);o.set("session",JSON.createObjectNode().put("id",session.wire().id()).put("generation",session.wire().generation()).put("kind",session.wire().kind()));o.set("arguments",JSON.valueToTree(args));o.set("value",value);return value;}
 static List<Object> list(JsonNode value){var result=new ArrayList<Object>();for(var v:value)result.add(JSON.convertValue(v,Object.class));return result;}
 public static void main(String[] args)throws Exception{var spec=JSON.readTree(ROOT.resolve("scenario.json").toFile());String host=JSON.readTree(ROOT.resolve("source-provenance.json").toFile()).path("host").asText();EchoAgentClient sdk=null;long hostPid=0;
  try{sdk=await(EchoAgentClient.spawn(host,List.of("--config",WORK.resolve("host.json").toString()),Path.of("/Users/ls/MyWork/code/ylp_agent_learn/lp-agent/.worktrees/echo-agent-sdk-worktrees/sdk-semantic-governance/sdks/shared/facade-operation-catalog.json"),Path.of("/Users/ls/MyWork/code/ylp_agent_learn/lp-agent/.worktrees/echo-agent-sdk-worktrees/sdk-semantic-governance/sdks/shared/contract-digests.json"),Map.of()));hostPid=ProcessHandle.current().descendants().filter(p->p.info().command().orElse("").equals(host)).mapToLong(ProcessHandle::pid).findFirst().orElse(0);check(hostPid>0,"native Host PID missing");var agent=await(sdk.createAgent());var a=await(agent.createSession(WORK.toString()));var b=await(agent.createSession(WORK.toString()));save("connected",JSON.createObjectNode().put("host_pid",hostPid));
   var stats=call(a,"permission.stats",List.of());long ttl=stats.path("ttl_ms").asLong();check(ttl==1800000,"wrong actual default ttl");check(stats.path("per_tool_entries").asInt()==0&&stats.path("global_entries").asInt()==0,"cache not empty");
   for(var e:spec.path("entries"))call(a,"permission.record_approval",list(e));long recorded=System.nanoTime();
   for(var e:spec.path("entries")){var input=list(e);check(call(a,"permission.is_approved",input.subList(0,3)).asBoolean(),"initial approval false");}
   check(!call(a,"permission.is_approved",List.of("scope 中文🙂","parameter-tool",Map.of("x",99))).asBoolean(),"different args matched");check(!call(b,"permission.is_approved",list(spec.path("entries").path(0)).subList(0,3)).asBoolean(),"other Session matched");check(call(a,"permission.is_approved",List.of("scope-β","global-tool",Map.of("different",true))).asBoolean(),"session_tool does not cover args");call(a,"permission.record_approval",list(spec.path("once")));check(!call(a,"permission.is_approved",list(spec.path("once")).subList(0,3)).asBoolean(),"once cached");check(call(a,"permission.cleanup_expired",List.of()).asLong()==0,"premature cleanup");stats=call(a,"permission.stats",List.of());check(stats.path("per_tool_entries").asInt()==2&&stats.path("global_entries").asInt()==2,"expected4entries");long deadline=recorded+TimeUnit.MILLISECONDS.toNanos(ttl+1500);
   while(System.nanoTime()<deadline){save("waiting_real_default_ttl",JSON.createObjectNode().put("host_pid",hostPid).put("ttl_ms",ttl).put("remaining_ms",Math.max(0,(deadline-System.nanoTime())/1_000_000)).put("recorded_monotonic_ns",Long.toString(recorded)));Thread.sleep(Math.min(5000,Math.max(1,(deadline-System.nanoTime())/1_000_000)));}
   long elapsed=(System.nanoTime()-recorded)/1_000_000;check(elapsed>=ttl+1500,"clock below actual TTL");for(var e:spec.path("entries"))check(!call(a,"permission.is_approved",list(e).subList(0,3)).asBoolean(),"expired entry true");stats=call(a,"permission.stats",List.of());check(stats.path("per_tool_entries").asInt()==2&&stats.path("global_entries").asInt()==2,"read must not remove entries");check(call(a,"permission.cleanup_expired",List.of()).asLong()==4,"cleanup must remove4");check(call(a,"permission.cleanup_expired",List.of()).asLong()==0,"second cleanup not0");stats=call(a,"permission.stats",List.of());check(stats.path("per_tool_entries").asInt()==0&&stats.path("global_entries").asInt()==0,"cache not empty after cleanup");call(a,"permission.record_approval",list(spec.path("entries").path(0)));check(call(a,"permission.is_approved",list(spec.path("entries").path(0)).subList(0,3)).asBoolean(),"manager not live after expiration");await(b.closeAsync());await(a.closeAsync());await(agent.closeAsync());sdk.close();check(!ProcessHandle.of(hostPid).map(ProcessHandle::isAlive).orElse(false),"Host still running");save("passed",JSON.createObjectNode().put("actual_wait_ms",elapsed).put("ttl_ms",ttl).put("host_pid",hostPid).put("host_alive_after_close",false).put("host_sha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(Path.of(host))))));
  }catch(Throwable e){save("failed",JSON.createObjectNode().put("error",e.toString()).put("host_pid",hostPid));throw e;}finally{if(sdk!=null)sdk.close();}
 }
}
